//autogenerated:yes
//nolint:revive,govet,errcheck
package marsh_test

import (
	"testing"

	"github.com/stretchr/testify/require"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/marsh"
)

func TestEnum_MOTION_PLATFORM_HEALTH(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.MOTION_PLATFORM_HEALTH
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.MOTION_PLATFORM_HEALTH_OK.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.MOTION_PLATFORM_HEALTH
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.MOTION_PLATFORM_HEALTH_OK, dec)
	})
}
